import{_ as d,C as s,o as r,c,a6 as i,E as a,j as t,a as l}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"File Upload","description":"Extension parsing, content-type trust, polyglots, path traversal in filenames, and race-condition uploads.","frontmatter":{"title":"File Upload","description":"Extension parsing, content-type trust, polyglots, path traversal in filenames, and race-condition uploads."},"headers":[],"relativePath":"file-upload/index.md","filePath":"file-upload/index.md"}'),p={name:"file-upload/index.md"};function h(u,e,m,b,f,y){const o=s("LabGroup"),n=s("TopicComplete");return r(),c("div",null,[e[0]||(e[0]=i('<h1 id="file-upload-vulnerabilities" tabindex="-1">File Upload Vulnerabilities <a class="header-anchor" href="#file-upload-vulnerabilities" aria-label="Permalink to &quot;File Upload Vulnerabilities&quot;">​</a></h1><p class="wd-section-lede">An upload form is a bridge from an untrusted byte stream to a trusted filesystem. The vulnerability appears when the server decides what a file <em>is</em> using a property the client controls, or when a file the server accepts can later be executed.</p><div class="wd-callout"><p><strong>The model.</strong> Three questions decide the outcome: <em>where</em> does the file land, <em>what name</em> does it get, and <em>who parses it</em>? A <code>.php</code> file in an executable directory is code. The same bytes in a static directory are data. Most defences fail because they answer only one of the three.</p></div><h2 id="what-the-server-actually-checks" tabindex="-1">What the server actually checks <a class="header-anchor" href="#what-the-server-actually-checks" aria-label="Permalink to &quot;What the server actually checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>What the client controls</th><th>Typical failure</th></tr></thead><tbody><tr><td><code>Content-Type</code> header</td><td>entirely</td><td>trust it as proof of file type</td></tr><tr><td>Filename extension</td><td>entirely</td><td>blocklist misses <code>.phtml</code>, <code>.php5</code>, <code>.phar</code></td></tr><tr><td>Magic bytes</td><td>the first bytes</td><td>a polyglot satisfies two parsers</td></tr><tr><td>Image re-encoding</td><td>output</td><td>skipped, or only resized</td></tr><tr><td>Destination path</td><td>filename traversal</td><td><code>../../</code> writes outside the upload directory</td></tr><tr><td>Execution config</td><td>server</td><td>upload directory has a PHP handler</td></tr></tbody></table><details class="details custom-block"><summary>🔬 Under the Hood: why <code>shell.php.jpg</code> sometimes works</summary><p>Apache with <code>mod_mime</code> and <code>MultiViews</code> resolves extensions right-to-left and can treat <code>shell.php.jpg</code> as PHP if any segment is a handler. IIS historically truncated at the semicolon (<code>shell.asp;.jpg</code>) and parsed <code>shell.asp</code> as ASP. Nginx with <code>cgi.fix_pathinfo=1</code> can execute <code>/uploads/shell.jpg/x.php</code> as PHP because it passes the path to PHP-FPM and PHP walks back to the first existing file.</p><p>These are not &quot;filter bypasses&quot; in the application — they are <strong>server configuration</strong> bugs. The upload control cannot fix a directory that executes arbitrary extensions.</p></details><details class="details custom-block"><summary>⚙️ Engine Variations: executable extensions by stack</summary><ul><li><strong>PHP:</strong> <code>.php</code>, <code>.php3</code>, <code>.php4</code>, <code>.php5</code>, <code>.phtml</code>, <code>.phar</code> (deserialization on file operations).</li><li><strong>ASP.NET:</strong> <code>.aspx</code>, <code>.ashx</code>, <code>.asmx</code>, <code>.config</code> (web.config can add handlers).</li><li><strong>Java:</strong> <code>.jsp</code>, <code>.jspx</code>, <code>.war</code> (if auto-deploy is enabled).</li><li><strong>Node:</strong> no extension execution by default; the risk is a static server that maps <code>.js</code> and a template engine that evaluates uploaded content.</li><li><strong>Python:</strong> <code>.py</code> only if the app imports or execs it; <code>.pkl</code>/<code>.joblib</code> are deserialization sinks.</li></ul></details><h2 id="direct-execution" tabindex="-1">Direct execution <a class="header-anchor" href="#direct-execution" aria-label="Permalink to &quot;Direct execution&quot;">​</a></h2><p>If uploads land in a web-served, executable directory, the filename is the exploit. A minimal PHP web shell reads a file or runs a command.</p>',9)),a(o,{ids:"file-upload-lab-file-upload-remote-code-execution-via-web-shell-upload, file-upload-lab-file-upload-web-shell-upload-via-content-type-restriction-bypass"}),e[1]||(e[1]=i('<h2 id="filename-and-path-tricks" tabindex="-1">Filename and path tricks <a class="header-anchor" href="#filename-and-path-tricks" aria-label="Permalink to &quot;Filename and path tricks&quot;">​</a></h2><ul><li><strong>Path traversal in the filename</strong> writes outside the intended directory, sometimes into a location that is served or executed.</li><li><strong>Extension blocklist bypass</strong> uses an alternative executable extension or a handler configuration file such as <code>.htaccess</code>.</li><li><strong>Obfuscated extension</strong> abuses trailing characters, case, or null bytes that the validator and the web server parse differently.</li></ul>',2)),a(o,{ids:"file-upload-lab-file-upload-web-shell-upload-via-path-traversal, file-upload-lab-file-upload-web-shell-upload-via-extension-blacklist-bypass, file-upload-lab-file-upload-web-shell-upload-via-obfuscated-file-extension"}),e[2]||(e[2]=t("h2",{id:"content-validation-and-polyglots",tabindex:"-1"},[l("Content validation and polyglots "),t("a",{class:"header-anchor",href:"#content-validation-and-polyglots","aria-label":'Permalink to "Content validation and polyglots"'},"​")],-1)),e[3]||(e[3]=t("p",null,"A polyglot is a file valid in two formats at once: a JPEG whose comment segment contains PHP, or a GIF header followed by JavaScript. If the server checks magic bytes and then serves the file with a script handler, the embedded code executes.",-1)),a(o,{ids:"file-upload-lab-file-upload-remote-code-execution-via-polyglot-web-shell-upload"}),e[4]||(e[4]=t("h2",{id:"race-conditions",tabindex:"-1"},[l("Race conditions "),t("a",{class:"header-anchor",href:"#race-conditions","aria-label":'Permalink to "Race conditions"'},"​")],-1)),e[5]||(e[5]=t("p",null,"Some uploads are validated, written to a temporary location, then moved or deleted. Between the write and the validation there is a window in which the file is reachable. Racing the request is often the only way to execute a file the application would otherwise reject.",-1)),a(o,{ids:"file-upload-lab-file-upload-web-shell-upload-via-race-condition"}),e[6]||(e[6]=i(`<details class="details custom-block"><summary>🔬 Under the Hood: validation is not atomic</summary><p>A typical flow is:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. receive multipart body      → /tmp/upload-1234</span></span>
<span class="line"><span>2. inspect magic bytes         → reject or accept</span></span>
<span class="line"><span>3. move to /var/www/uploads/</span></span>
<span class="line"><span>4. delete temp file</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>If step 2 fails but step 1 already made the file web-accessible (for example, the upload directory is served directly), the payload executes before the rejection. Racing requires many parallel requests because the window is milliseconds; the goal is to hit the gap between write and unlink.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Store uploads outside the web root, generate a random filename with a safe extension, validate by decoding the file with a real parser (not by header or magic bytes), re-encode images, serve downloads through an application endpoint with <code>Content-Disposition: attachment</code> and <code>X-Content-Type-Options: nosniff</code>, and never let the upload directory execute anything.</p></div>`,2)),a(n,{"topic-id":"file-upload-vulnerabilities",label:"Mark file upload complete"})])}const w=d(p,[["render",h]]);export{v as __pageData,w as default};
